from typing import List

MOD = 998244353


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    """Given lowercase s of length n, count length-m strings by LCS length."""
    # A row of the LCS table is determined by its n successive increments,
    # each of which is either zero or one. Encode those increments as a mask.
    size = 1 << n
    rows = [[0] * (n + 1) for _ in range(size)]
    for mask in range(size):
        row = rows[mask]
        for i in range(n):
            row[i + 1] = row[i] + ((mask >> i) & 1)

    chars = sorted(set(s))
    multiplicity = {c: 1 for c in chars}
    multiplicity[""] = 26 - len(chars)

    # Precompute transitions; all letters absent from s have the same effect.
    transitions = {}
    for c in chars + [""]:
        trans = [0] * size
        for mask, old in enumerate(rows):
            new = [0] * (n + 1)
            for i in range(1, n + 1):
                match = c != "" and s[i - 1] == c
                new[i] = max(old[i], new[i - 1], old[i - 1] + match)
            bits = 0
            for i in range(n):
                if new[i + 1] > new[i]:
                    bits |= 1 << i
            trans[mask] = bits
        transitions[c] = trans

    dp = [0] * size
    dp[0] = 1
    for _ in range(m):
        nxt = [0] * size
        for c, mult in multiplicity.items():
            if not mult:
                continue
            trans = transitions[c]
            for mask, count in enumerate(dp):
                if count:
                    dest = trans[mask]
                    nxt[dest] = (nxt[dest] + count * mult) % MOD
        dp = nxt

    ans = [0] * (n + 1)
    for mask, count in enumerate(dp):
        if count:
            ans[rows[mask][n]] = (ans[rows[mask][n]] + count) % MOD
    return ans

