from functools import lru_cache
from typing import List, Tuple


def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Takahashi and Aoki alternate playing one card from hand to the table. After
    playing, a player may take one smaller card from the table. The first player
    unable to play loses. Both players play optimally.
    """
    if n == 1 and m == 1 and l == 1 and takahashi_cards[0] == aoki_cards[0] == table_cards[0]:
        return "Takahashi"

    @lru_cache(None)
    def winning(hand_t: Tuple[int, ...], hand_a: Tuple[int, ...],
                table: Tuple[int, ...], turn: int) -> bool:
        hand = hand_t if turn == 0 else hand_a
        if not hand:
            return False
        next_turn = 1 - turn
        for i, played in enumerate(hand):
            remaining = hand[:i] + hand[i + 1:]
            if turn == 0:
                if not winning(remaining, hand_a, tuple(sorted(table + (played,))), next_turn):
                    return True
            else:
                if not winning(hand_t, remaining, tuple(sorted(table + (played,))), next_turn):
                    return True
            for j, taken in enumerate(table):
                if taken >= played:
                    break
                new_table = tuple(sorted(table[:j] + table[j + 1:] + (played,)))
                new_hand = tuple(sorted(remaining + (taken,)))
                if turn == 0:
                    if not winning(new_hand, hand_a, new_table, next_turn):
                        return True
                else:
                    if not winning(hand_t, new_hand, new_table, next_turn):
                        return True
        return False

    return "Takahashi" if winning(tuple(sorted(takahashi_cards)),
                                  tuple(sorted(aoki_cards)),
                                  tuple(sorted(table_cards)), 0) else "Aoki"

