from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether available rectangular tiles can exactly cover the grid."""
    if h <= 0 or w <= 0:
        return False
    pieces = list(tiles[:n])
    target = h * w
    areas = [a * b for a, b in pieces]
    if any(a <= 0 or b <= 0 for a, b in pieces):
        return False
    if sum(areas) < target:
        return False
    full = (1 << target) - 1

    # A subset-sum table prunes states where the remaining pieces cannot
    # account for exactly the number of uncovered cells.
    @lru_cache(None)
    def subset_possible(mask: int, area: int) -> bool:
        if area == 0:
            return True
        if mask == 0 or area < 0:
            return False
        bit = mask & -mask
        i = bit.bit_length() - 1
        rest = mask ^ bit
        return subset_possible(rest, area) or subset_possible(rest, area - areas[i])

    @lru_cache(None)
    def search(occupied: int, used: int) -> bool:
        remaining = target - occupied.bit_count()
        if remaining == 0:
            return True
        unused = ((1 << len(pieces)) - 1) ^ used
        if not subset_possible(unused, remaining):
            return False

        # The first unoccupied cell in row-major order must be the top-left
        # cell of whichever rectangle covers it.
        first = next(i for i in range(target) if not (occupied >> i) & 1)
        y, x = divmod(first, w)
        for i, (a, b) in enumerate(pieces):
            if (used >> i) & 1:
                continue
            for dh, dw in {(a, b), (b, a)}:
                if y + dh > h or x + dw > w:
                    continue
                placement = 0
                row_bits = (1 << dw) - 1
                for yy in range(y, y + dh):
                    placement |= row_bits << (yy * w + x)
                if not occupied & placement and search(occupied | placement, used | (1 << i)):
                    return True
        return False

    return search(0, 0)

