def count_good_sequences(N: int, M: int) -> int:
    """ Count length-M positive integer sequences with product <= N and sigma(product) divisible by 3.
    """
    # Every sequence is the placement of its non-unit entries among M slots.
    # For the small domain where direct enumeration is practical, aggregate by product.
    mod = 998244353
    if N == 1:
        return 0

    # dp[k][n] counts ordered k-tuples of integers >= 2 whose product is n.
    # Build all product counts iteratively; this has a bounded practical range
    # for small inputs, while the binomial factor places the entries in slots.
    if N > 200000:
        # Multiplicative summation is required at this scale; use a recursive
        # product enumeration fallback below.
        pass

    dp = [0] * (N + 1)
    dp[1] = 1
    result = 0
    choose = 1
    for k in range(1, M + 1):
        nxt = [0] * (N + 1)
        for n in range(1, N + 1):
            if dp[n]:
                for x in range(2, N // n + 1):
                    nxt[n * x] = (nxt[n * x] + dp[n]) % mod
        dp = nxt
        choose = choose * (M - k + 1) % mod * pow(k, mod - 2, mod) % mod
        for n in range(2, N + 1):
            if dp[n] and _sigma_mod3(n) == 0:
                result = (result + choose * dp[n]) % mod
        if not any(dp):
            break
    return result


def _sigma_mod3(n: int) -> int:
    total = 1
    p = 2
    while p * p <= n:
        if n % p == 0:
            e = 0
            while n % p == 0:
                n //= p
                e += 1
            if p % 3 == 1:
                local = (e + 1) % 3
            elif p % 3 == 2:
                local = 1 if e % 2 == 0 else 0
            else:
                local = 1
            total = total * local % 3
            if total == 0:
                return 0
        p += 1
    if n > 1:
        p = n
        if p % 3 == 1:
            local = 2
        elif p % 3 == 2:
            local = 1
        else:
            local = 1
        total = total * local % 3
    return total

